h,w=20,13
G=[[4]*w for _ in range(h)]
# Existing stencil in the input, retained as the template.
seed={(11,7):5,(11,8):5,(12,6):8,(12,7):5,(12,8):8,(13,6):8,(13,7):5,(13,8):0}
for (r,c),v in seed.items(): G[r][c]=v
markers=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
stencil=[[(None,5,5),(8,5,8),(8,5,0)]]
for r,c in markers:
    for dr,row in zip((-1,0,1),stencil[0]):
        for dc,v in zip((-1,0,1),row):
            if v is not None: G[r+dr][c+dc]=v
print('\n'.join('['+', '.join(map(str,row))+']' for row in G))
